<?php
if(!is_user_logged_in()){wp_safe_redirect(gc_page_url('premium-login'));exit;} get_header(); $lesson_id=get_the_ID(); $required=(int)(get_post_meta($lesson_id,'gc_lesson_tier',true)?:1); $user_tier=function_exists('gc_get_user_premium_tier')?gc_get_user_premium_tier(get_current_user_id()):1; if($required>$user_tier){ echo '<main class="gc-section"><div class="gc-container"><div class="gc-location-result"><span class="gc-kicker">Member Hub</span><h1>Higher tier required</h1><p>This lesson is available from '.esc_html(function_exists('gc_tier_label')?gc_tier_label($required):'Tier '.$required).' upward.</p><a class="gc-button gc-button-green" href="'.esc_url(gc_page_url('premium-dashboard')).'">Return to Member Hub</a></div></div></main>'; get_footer(); exit; } $done=in_array($lesson_id,(array)get_user_meta(get_current_user_id(),'gc_completed_lessons',true),true); $video=get_post_meta($lesson_id,'gc_lesson_video_url',true); $file=(int)get_post_meta($lesson_id,'gc_lesson_video_file_id',true); $external=get_post_meta($lesson_id,'gc_lesson_external_url',true); ?>
<main class="gc-section gc-lesson-page"><div class="gc-container gc-lesson-wrap"><a class="gc-back-link" href="<?php echo esc_url(gc_page_url('premium-dashboard')); ?>#learning">← Back to Member Hub</a><div class="gc-lesson-head"><span class="gc-kicker">Lesson · <?php echo esc_html(function_exists('gc_tier_label')?gc_tier_label($required):'Tier '.$required); ?></span><h1><?php the_title(); ?></h1></div><article class="gc-lesson-content"><?php the_content(); ?><?php if($video): ?><div class="gc-lesson-video"><iframe src="<?php echo esc_url(function_exists('gc_lesson_embed_src')?gc_lesson_embed_src($video):$video); ?>" title="<?php the_title_attribute(); ?>" loading="lazy" allowfullscreen></iframe></div><?php endif; ?><?php if($file){$url=wp_get_attachment_url($file);if($url):?><p><a class="gc-button gc-button-light" href="<?php echo esc_url($url); ?>">Open lesson file →</a></p><?php endif;} ?><?php if($external): ?><p><a class="gc-button gc-button-gold" target="_blank" rel="noopener" href="<?php echo esc_url($external); ?>">Start external lesson →</a></p><?php endif; ?></article><div class="gc-lesson-complete"><?php if($done): ?><span class="gc-card-status">✓ Completed</span><?php else: ?><a class="gc-button gc-button-green" href="<?php echo esc_url(wp_nonce_url(add_query_arg('gc_complete_lesson',$lesson_id,home_url('/')),'gc_complete_'.$lesson_id)); ?>">Mark lesson complete</a><?php endif; ?></div></div></main>
<?php get_footer(); ?>
